33	function makeCity(seed, x0, x1, base, [lo, hi], [wLo, wHi], odds) {
34	  const r = rng(seed), out = [], lamps = [];
35	  for (let x = x0; x < x1;) {
36	    const w = Math.round(wLo + r() * (wHi - wLo)), top = Math.round(lo + r() * (hi - lo));
37	    out.push([x, top, w, base - top]);
38	    for (let y = top + 3; y < base - 1; y += 4) for (let lx = x + 2; lx < x + w - 1; lx += 3) if (r() < odds) lamps.push([lx, y]);
39	    x += w;
40	  }
41	  return {out, lamps};
42	}
