      if (Math.abs(a.size - b.size) > 0.5) parts.push(`size ${a.size}->${b.size}`);
      for (const k of ['facing', 'action', 'expr']) if (a[k] !== b[k]) parts.push(`${k} ${a[k]}->${b[k]}`);
      if (parts.length) issues.push(`${id}: ${parts.join(', ')}`);
