const seam = shot => {
  const before = frameAt(shot.start - 1e-3), wiped = frameAt(shot.start + 1e-3).wipe !== null;
  return {before, wiped, after: frameAt(shot.start + (wiped ? WIPE_SECONDS * 0.5 : 0) + 1e-3)};
