    const frame = frameAt(t);
    if (!frame.wipe && !previous.wipe) {
      assert.ok(Math.abs(frame.cam.z - previous.cam.z) <= 0.75, `${t} 相机倍数跳变`);
      assert.ok(Math.hypot(frame.cam.cx - previous.cam.cx, frame.cam.cy - previous.cam.cy) <= 12, `${t} 相机位置跳变`);
