  "content": "import {writeFile} from 'node:fs/promises';
import path from 'node:path';
import {openChrome, root} from '../../會呼吸的痛/開場樣圖/v2/chrome.mjs';
import {SHOTS} from '../../會呼吸的痛/MV/shots.js';

const pick = ['P02', 'L05', 'L06', 'L07', 'L13', 'L14', 'I02', 'L15', 'L17', 'L18', 'L19', 'L21', 'L27', 'L31', 'L33', 'L34'];
const tiles = pick.flatMap(id => {
  const i = SHOTS.findIndex(s => s.id === id), t = SHOTS[i].start, open = ['L27', 'L34'].includes(id);
  return [[`${SHOTS[i - 1].id} ${t.toFixed(3)}-`, t - 0.001], [`${id} ${open ? '+1f' : 'reveal'}`, t + (open ? 0.083 : 0.535)]];
});
tiles.push(['P02 walk 11.0', 11], ['P02 lay 13.5', 13.5], ['L17 leave 147.3', 147.3], ['L34 walk 232.8', 232.8]);
const COLS = 4, TW = 480, TH = 270, ROWS = Math.ceil(tiles.length / COLS);
const chrome = await openChrome();
try {
  await chrome.openStyle('storyboard', path.join(root, '會呼吸的痛/MV'));
  await chrome.evaluate(`(() => {
    const sheet = document.createElement('canvas');
    sheet.width = ${COLS * TW}; sheet.height = ${ROWS * TH};
    const ctx = sheet.getContext('2d');
    ctx.fillStyle = '#eee8d9'; ctx.fillRect(0, 0, sheet.width, sheet.height);
    ctx.imageSmoothingEnabled = false; ctx.font = '18px Menlo, monospace';
    window.sheet = sheet;
    window.addTile = (i, label) => {
      const x = (i % ${COLS}) * ${TW}, y = Math.floor(i / ${COLS}) * ${TH};
      ctx.drawImage(window.art.canvas, x, y, ${TW - 4}, ${TH - 4});
      const width = ctx.measureText(label).width + 12;
      ctx.fillStyle = 'rgba(53,46,42,.82)'; ctx.fillRect(x, y, width, 26);
      ctx.fillStyle = '#fff'; ctx.fillText(label, x + 6, y + 19);
    };
  })()`);
  for (const [i, [label, t]] of tiles.entries()) {
    await chrome.evaluate(`window.renderAt(${t})`);
    await chrome.evaluate(`window.addTile(${i}, ${JSON.stringify(label)})`);
  }
  console.log('renderErrors', JSON.stringify(await chrome.evaluate('window.renderErrors')));
  const png = await chrome.evaluate(`window.sheet.toDataURL('image/png').split(',')[1]`);
  await writeFile(path.join(root, '.agent/visual/轉場接縫.png'), Buffer.from(png, 'base64'));
} finally {
  await chrome.close();
}
"
